// ============================================================================
// File: ExportResponse.cs
// Project: PlantSafety.Api
// Author: David (Ted)
// Created: 2026-06-13
// Last Updated: 2026-06-13
// Description: Response payload for all PlantSafety.Api export endpoints.
//              Contains a presigned Azure Blob Storage download URL and metadata
//              about the generated file.
// ============================================================================
//
// Onboarding Notes:
// - The DownloadUrl is a presigned Azure Blob SAS URL generated by the
//   Infrastructure layer. It expires at ExpiresAt (typically 15 minutes from
//   generation). Clients must download the file before expiry.
// - ContentType maps to the requested ExportFormat:
//     Csv   → "text/csv"
//     Excel → "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
//     Pdf   → "application/pdf"
// - RecordCount is the actual number of records exported, which may be less than
//   ExportRequest.MaxRecords if the data set is smaller.
// - Returned as the Data payload inside ApiResponse<ExportResponse>.
//
// Rationale:
// - Using a presigned URL rather than streaming binary through the API avoids
//   memory pressure on API pods for large exports and decouples file delivery
//   from the request/response cycle.
//
// Future Extension Seams:
// - Add JobId (Guid?) for async large exports where generation is queued and
//   the client polls a status endpoint rather than receiving the URL synchronously.
// - Add ExpiresAfterSeconds as a convenience alongside ExpiresAt.
//
// ============================================================================

namespace PlantSafety.Api.Models.Exports;

/// <summary>
/// Response payload returned by all PlantSafety.Api module export endpoints.
/// Contains a presigned download URL and file metadata.
/// </summary>
/// <param name="FileName">The suggested download file name (e.g. <c>"compliance-export-2026-06-13.xlsx"</c>).</param>
/// <param name="ContentType">MIME type of the generated file.</param>
/// <param name="DownloadUrl">Presigned Azure Blob SAS URL. Expires at <see cref="ExpiresAt"/>.</param>
/// <param name="ExpiresAt">UTC timestamp when the <see cref="DownloadUrl"/> becomes invalid.</param>
/// <param name="RecordCount">Actual number of records included in the export.</param>
public sealed record ExportResponse(
    string          FileName,
    string          ContentType,
    string          DownloadUrl,
    DateTimeOffset  ExpiresAt,
    int             RecordCount);
